WITH by_dimension AS (SELECT o.status AS order_status, a.status AS payment_status, COUNT(*) AS num_rows, MIN(a.amount) AS min_amount FROM payments a JOIN orders o ON a.order_id = o.id GROUP BY GROUPING SETS ((o.status, a.status), (o.status))) SELECT order_status, payment_status, num_rows, CASE WHEN payment_status RLIKE '^(FAILED|REFUNDED)$' THEN 'CORE' ELSE 'PRIORITY' END AS payment_status_zone FROM by_dimension ORDER BY order_status DESC, payment_status ASC;
